DO $k6p18$
DECLARE ocr_id bigint;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM document WHERE id = 4631 AND is_active AND sha256 = 'b3d44788806f4e618942a2c72ac95c069e2675c6c78595fbab305c5760ddf683') THEN
        RAISE EXCEPTION 'document 4631 is not the active source the export reviewed';
    END IF;
    SELECT c.id INTO ocr_id FROM page_ocr_candidate c WHERE c.id = 1502 AND c.document_id = 4631 AND c.page_no = 18
       AND encode(sha256(convert_to(c.text, 'UTF8')), 'hex') = 'e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' AND c.word_count = 0;
    IF ocr_id IS NULL THEN RAISE EXCEPTION 'page 18: the reviewed OCR candidate 1502 is not this empty page''s';
    END IF;
    IF coalesce((SELECT decision FROM page_ocr_adjudication WHERE candidate_id = ocr_id
                 ORDER BY decided_at DESC, id DESC LIMIT 1), 'none') <> 'rejected' THEN
        RAISE EXCEPTION 'page 18: record the export first (the OCR candidate is not rejected)';
    END IF;
    IF EXISTS (SELECT 1 FROM page_ocr_candidate c JOIN LATERAL (SELECT decision FROM page_ocr_adjudication a
                WHERE a.candidate_id = c.id ORDER BY a.decided_at DESC, a.id DESC LIMIT 1) l ON true
               WHERE c.document_id = 4631 AND c.page_no = 18 AND l.decision = 'accepted'
                 AND c.engine <> 'owner-transcription/1') THEN
        RAISE EXCEPTION 'page 18 already has another accepted reading';
    END IF;
END $k6p18$;
